function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 400000) return 's needs 1 to 4 * 10^5 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may only contain lowercase English letters.';
  return null;
}

