function lastSubstring(s) {
  const n = s.length;
  let best = 0;
  let candidate = 1;
  let offset = 0;

  while (candidate + offset < n) {
    const bestChar = s[best + offset];
    const candidateChar = s[candidate + offset];
    if (bestChar === candidateChar) {
      offset++;
    } else if (bestChar > candidateChar) {
      candidate = candidate + offset + 1;
      offset = 0;
    } else {
      best = Math.max(best + offset + 1, candidate);
      candidate = best + 1;
      offset = 0;
    }
  }
  return s.slice(best);
}

