function lastSubstring(s) {
  let answer = '';
  for (let start = 0; start < s.length; start++) {
    for (let end = start + 1; end <= s.length; end++) {
      const piece = s.slice(start, end);
      if (piece > answer) answer = piece;
    }
  }
  return answer;
}

