function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (alphabet) => alphabet[int(0, alphabet.length - 1)];
  if (size === 'small') {
    const alphabet = letters.slice(rand() < 0.3 ? 23 : 0, [1, 2, 3, 26][int(0, 3)] + (rand() < 0.3 ? 23 : 0));
    const length = int(1, 12);
    let s = '';
    for (let i = 0; i < length; i++) s += pick(alphabet);
    return [s];
  }
  const length = 10000;
  const shape = int(0, 3);
  if (shape === 0) {
    // Long runs of the same block with an occasional change stress the skipping rule.
    const block = Array.from({ length: int(1, 6) }, () => pick('yz')).join('');
    let s = '';
    while (s.length < length) s += rand() < 0.02 ? pick('xyz') : block;
    return [s.slice(0, length)];
  }
  if (shape === 1) return ['z'.repeat(length - 1) + pick('abcdefghijklmnopqrstuvwxy')];
  const alphabet = shape === 2 ? 'ab' : letters;
  let s = '';
  for (let i = 0; i < length; i++) s += pick(alphabet);
  return [s];
}
